119:     ant.replaceregexp(match:'BLUEJ_VERSION = .*', replace:"BLUEJ_VERSION = \"${bluejVersion}\";", byline:true) {
120:         fileset(dir: '../boot/src/main/java/bluej/', includes: 'Boot.java')
121:     }
122:     // Update the shipped README:
123:     ant.replaceregexp(match:'BlueJ version .*\\b (\\s+--.*)', replace:"BlueJ version ${bluejVersion} \\1", byline:true) {
