129:     }
130:     ant.replaceregexp(match:'(\\s*VALUE \"\\w+Version\",).*', replace:"\\1 \"${bluejVersionNoSuffix}\"", byline:true) {
131:         fileset(dir: '../bluej/package/winlaunch', includes: 'bluej-version.rc')
132:     }
133:     // And in the launcher manifest:
134:     ant.replaceregexp(match:'(\\s*<assemblyIdentity\\s+version=)\".*\"', replace:"\\1\"${bluejVersionNoSuffix}.0\"", byline:true) {
135:         fileset(dir: '../bluej/package/winlaunch', includes: 'bjmanifest.xml')
136:     }
137:     def bjMSIProductId = versionProps["bluej-" + bluejVersion];
138:     // Update the WiX build files with the GUID:
139:     ant.replaceregexp(match:'<Product Version=\'.*\' Id=\'.*\'', replace:"<Product Version='${bluejVersionNoSuffix}' Id='${bjMSIProductId}'", byline:true) {
140:         fileset(dir: '../bluej/package/winsetup', includes: 'bluej.wxs')
141:     }
142:     ant.replaceregexp(match:'(\\s*<Property\\s+Id=\"SOFTWAREVERSION\"\\s+Value=).*', replace:"\\1\"${bluejVersionNoSuffix}\"/>", byline:true) {
143:         fileset(dir: '../bluej/package/winsetup', includes: 'bluej.wxs')
144:     }
145:     ant.replaceregexp(match:'(\\s+Maximum=)\".*\"', replace:"\\1\"${bluejVersionNoSuffix}\"", byline:true) {
146:         fileset(dir: '../bluej/package/winsetup', includes: 'bluej.wxs')
147:     }
148: 
149:     //////////////////////////////////////
150:     // Greenfoot:
